import { connect, mapProps, mapReadPretty } from '@formily/react';
import {
  Radio as ArcoRadio,
  RadioProps as ArcoRadioProps,
  RadioGroupProps as ArcoRadioGroupProps,
} from '@arco-design/web-react';
import { PreviewText } from '../PreviewText';

type ComposedRadio = React.FC<React.PropsWithChildren<ArcoRadioProps>> & {
  Group?: React.FC<React.PropsWithChildren<ArcoRadioGroupProps>>;
  __ARCO_RADIO?: boolean;
};

export const Radio: ComposedRadio = connect(ArcoRadio);

const Group = connect(
  ArcoRadio.Group,
  mapProps({ dataSource: 'options' }),
  mapReadPretty(PreviewText.Select)
);

Radio.Group = Group;
Radio.__ARCO_RADIO = true;

export default Radio;
